package io.xeros.content.questing;
import io.xeros.model.entity.player.Player;import io.xeros.model.entity.npc.NPC;import java.util.*;
public final class CooksAssistant extends ClassicQuest {
 public CooksAssistant(Player p){super(p);}public String getName(){return "Cook's Assistant";}public String getDisplayName(){return "Assistente do cozinheiro";}public int getCompletionStage(){return 8;}
 public List<String> getCompletedRewardsList(){return Arrays.asList("1 ponto de missao","300 Cooking XP","Acesso ao Cook-o-matic range");}
 public List<String> getJournalText(int s){if(s==0)return Arrays.asList("Fale com Cook na cozinha do castelo de Lumbridge.","Ele precisa preparar o bolo de aniversario do Duke Horacio.");if(s==8)return Arrays.asList("Entreguei os ingredientes do bolo ao Cook.","Posso usar o Cook-o-matic range do castelo.");int m=s-1;return Arrays.asList("Ajude Cook a preparar o bolo de aniversario.",((m&1)!=0?"@gre@Entregue: ":"Falta: ")+"Egg (galinheiro a noroeste).",((m&2)!=0?"@gre@Entregue: ":"Falta: ")+"Bucket of milk (use Bucket na Dairy cow).",((m&4)!=0?"@gre@Entregue: ":"Falta: ")+"Pot of flour (moinho ao norte).","Use Grain no Hopper no ultimo andar e acione os controles.","Colete a farinha com um Pot no andar terreo.");}
 public void giveQuestCompletionRewards(){exactReward(7,300);}
 public boolean handleNpcClick(NPC n,int option){if(n.getNpcId()!=4626||!local(n,3209,3215,0))return false;if(option!=1||!ready()||!nearbyNpc(n))return true;int s=getStage();
 if(s==0)offer(n,0,"O aniversario do Duke Horacio e hoje! Preciso de Egg, Bucket of milk e Pot of flour para o bolo.","Vou ajudar com os ingredientes.",()->{step(0,1);say(n.getNpcId(),"Obrigado! Ha galinhas a noroeste, vacas ao norte e um moinho perto da fazenda.","Posso receber os ingredientes aos poucos.");});
 else if(isQuestCompleted())say(n.getNpcId(),"O bolo ficou pronto a tempo. Muito obrigado!","O Cook-o-matic range da cozinha agora esta a sua disposicao.");
 else offer(n,s,"Conseguiu algum dos tres ingredientes para o bolo?","Entregar os ingredientes que tenho.",()->{int mask=s-1;List<int[]> cost=new ArrayList<>();int[] ids={1944,1927,1933};for(int i=0;i<3;i++)if((mask&(1<<i))==0&&has(ids[i])){cost.add(new int[]{ids[i],1});mask|=1<<i;}if(cost.isEmpty()){say(n.getNpcId(),"Ainda preciso dos ingredientes que faltam no seu diario.");return;}if(!exchange(cost.toArray(new int[0][]),new int[0][]))return;int next=mask+1;if(next==8)finish(s,7,300);else{step(s,next);say(n.getNpcId(),"Obrigado! Guardei estes ingredientes; traga os que ainda faltam.");}});return true;}
 public static boolean rangeAllowed(Player p,int object){if(object!=114)return true;for(Quest q:p.getQuesting().getQuestList())if(q instanceof CooksAssistant&&q.isQuestCompleted())return true;p.sendMessage("Cook pede que voce conclua Cook's Assistant antes de usar este fogao.");return false;}
 public static int burnLevel(Player p,int raw,int object,int normal){if(object!=114||p.heightLevel!=0||Math.abs(p.absX-3212)>4||Math.abs(p.absY-3215)>4)return normal;for(Quest q:p.getQuesting().getQuestList())if(q instanceof CooksAssistant&&q.isQuestCompleted()){switch(raw){case 2307:return 34;case 2132:case 2138:case 317:case 321:return 31;case 327:return 34;case 345:return 38;case 353:return 41;case 2321:return 42;case 335:return 45;case 341:return 46;case 349:case 2319:return 49;case 2001:return 54;case 331:return 55;case 19656:return 52;case 21684:return 60;default:return normal;}}return normal;}
}
